const input = $input.first().json;
const analysisRunId = String(input.analysis_run_id ?? '').trim();
const pipelineVersion = String(input.pipeline_version ?? '').trim();
const replicateIndex = Number(input.replicate_index);
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu.test(analysisRunId)) throw new Error('[AGENTIC_INPUT_INVALID] analysis_run_id must be a UUID');
if (pipelineVersion !== 'tender_agentic_pipeline_v1') throw new Error('[AGENTIC_INPUT_INVALID] pipeline_version must be tender_agentic_pipeline_v1');
if (!Number.isInteger(replicateIndex) || replicateIndex < 1) throw new Error('[AGENTIC_INPUT_INVALID] replicate_index must be an integer >= 1');
return [{json:{analysis_run_id:analysisRunId,pipeline_version:pipelineVersion,replicate_index:replicateIndex}}];

const value=$input.first().json;
if (!['dispatch','retry','noop','reject'].includes(value.action)) throw new Error('[AGENTIC_PREFLIGHT_FAILED] preflight returned no bounded action');
if (value.action==='reject') throw new Error('[AGENTIC_MANIFEST_INCOMPLETE] registered manifest is missing, failed, incomplete, or has zero processable documents');
return [{json:value}];

const response=$input.first().json; const expected=$('Разобрать решение').first().json;
const body=response.body??response;
if (body.job_id!==expected.job_id || body.field_catalog_sha256!=='ABCBEA68911CE9FFAD9D436C9EABE708E12DBC4F04F7D5591CAFE4C58359B843' || !/^[0-9a-f]{64}$/u.test(String(body.input_manifest_sha256??''))) throw new Error('[AGENTIC_SEAL_IDENTITY_MISMATCH] runner seal identity/hash mismatch');
return [{json:{...expected,input_manifest_sha256:body.input_manifest_sha256}}];

const source=$input.first().json; const context=$('Разобрать решение').first().json;
let document=null; try { document=$('Документы по одному').item.json.documents??null; } catch {}
return [{json:{job_id:context.job_id,source_document_id:document?.source_document_id??null,
error_code:String(source.error_code??source.body?.error?.code??'AGENTIC_DISPATCH_FAILED').slice(0,80),
error_message:'Agentic dispatch step failed'}}];

const job=$input.first().json;
if (job.action!=='retry' || !/^[0-9a-f]{64}$/iu.test(String(job.input_manifest_sha256??''))) throw new Error('[AGENTIC_RETRY_CONTRACT_INVALID] retry requires sealed manifest identity');
return [{json:job}];

const response=$input.first().json; const document=$('Документы по одному').item.json; const body=response.body??response;
if (Number(response.statusCode??200)!==200 || body.job_id!==document.job_id || body.artifact_key!==document.documents.artifact_key ||
 String(body.sha256??'').toUpperCase()!==String(document.documents.source_sha256??'').toUpperCase() || Number(body.byte_size)!==Number(document.documents.byte_size)) {
 throw new Error('[AGENTIC_UPLOAD_IDENTITY_MISMATCH] runner upload identity/hash mismatch');
}
return [{json:{job_id:document.job_id,source_document_id:document.documents.source_document_id,artifact_key:document.documents.artifact_key,sha256:body.sha256}}];

const response=$input.first().json; const expected=$('Разобрать решение').first().json; const body=response.body??response;
let startInput=expected; try { startInput=$('Проверить sealed CAS').first().json; } catch { try { startInput=$('Подготовить retry start').first().json; } catch {} }
if (![200,202].includes(Number(response.statusCode??200)) || body.job_id!==expected.job_id || body.analysis_run_id!==expected.analysis_run_id ||
 body.pipeline_version!==expected.pipeline_version || body.field_catalog_version!==expected.field_catalog_version ||
 body.field_catalog_sha256!==expected.field_catalog_sha256 || body.input_manifest_sha256!==startInput.input_manifest_sha256 ||
 !['running','validating','completed'].includes(body.status) || !Number.isInteger(Number(body.attempt)) || Number(body.attempt)<1 || Number(body.attempt)>2)
 throw new Error('[AGENTIC_START_IDENTITY_MISMATCH] runner start outcome is ambiguous');
return [{json:{...expected,input_manifest_sha256:startInput.input_manifest_sha256,runner_status:body.status,runner_attempt:Number(body.attempt)}}];

const response=$input.first().json; const expected=$('Разобрать решение').first().json; const body=response.body??response;
if (![200,201].includes(Number(response.statusCode??200)) || body.job_id!==expected.job_id || body.analysis_run_id!==expected.analysis_run_id ||
 body.pipeline_version!==expected.pipeline_version || body.field_catalog_version!==expected.field_catalog_version ||
 body.field_catalog_sha256!==expected.field_catalog_sha256 || body.expected_documents!==expected.documents.length ||
 !['staging','ready'].includes(body.status)) throw new Error('[AGENTIC_RUNNER_JOB_IDENTITY_MISMATCH] runner job identity mismatch');
return [{json:expected}];

const value=$input.first().json;
if (value.outcome!=='updated' || Number(value.update_count)!==1) throw new Error('[AGENTIC_STAGED_OWNERSHIP_LOST] staged document CAS failed');
return $input.all();

const value=$input.first().json;
if (value.outcome!=='barrier_ok') throw new Error('[AGENTIC_STAGING_BARRIER_FAILED] '+String(value.outcome??'missing'));
return $input.all();

const value=$input.first().json;
if(value.outcome!=='updated'||Number(value.update_count)!==1) throw new Error('[AGENTIC_SEALED_OWNERSHIP_LOST] sealed ready CAS failed');
return $input.all();

const context=$('Разобрать решение').first().json;
let sealed=context; try { sealed=$('Проверить sealed CAS').first().json; } catch {}
return [{json:{job_id:context.job_id,input_manifest_sha256:sealed.input_manifest_sha256??context.input_manifest_sha256,
error_code:'START_OUTCOME_UNKNOWN',error_message:'Runner start acknowledgement is ambiguous; reconcile through idempotent status polling'}}];
